INSERT INTO public.seance_specs (corpse_id, requirements_md, design_md, invariants_json, approved_at)
VALUES (
  $lz$5a3f0c1e-0001-4000-8000-000000000001$lz$::uuid,
  $lz$# Requirements: Invoice totals calculator

## Acceptance Criteria

1. THE computeInvoiceTotal function SHALL return an object with the numeric fields subtotal, discount, tax, and total.
2. WHEN an item has a quantity of 0, THE computeInvoiceTotal function SHALL exclude that item from the subtotal.
3. WHEN the coupon is HALF, THE computeInvoiceTotal function SHALL set the discount to half of the unrounded subtotal.
4. WHEN the coupon is TEN, THE computeInvoiceTotal function SHALL set the discount to ten percent of the unrounded subtotal.
5. IF the coupon is any other value, THEN THE computeInvoiceTotal function SHALL set the discount to 0.
6. THE computeInvoiceTotal function SHALL compute the tax as the discounted subtotal multiplied by taxRate and SHALL round every returned amount to 2 decimal places.
7. THE computeInvoiceTotal function SHALL NOT read or modify any global state.
$lz$,
  $lz$# Design: Invoice totals calculator

Entry function: `computeInvoiceTotal(order)`.

Input: an object `{ items, taxRate, coupon }`. `items` is an array of `{ price: number, quantity: number }`, `taxRate` is a number where 0.2 means 20 percent, and `coupon` is a string.

Output: an object `{ subtotal, discount, tax, total }` whose fields are numbers rounded to two decimal places.

The function is pure and deterministic. The TypeScript version declares the input and output shapes as interfaces, replaces loose equality with strict equality, and keeps the arithmetic order unchanged.$lz$,
  $lz${"entry_function":"computeInvoiceTotal","input":"object { items: { price: number, quantity: number }[], taxRate: number, coupon: string }","output":"object { subtotal: number, discount: number, tax: number, total: number }","invariants":["Every returned amount is rounded to two decimal places with Math.round(value * 100) / 100.","Items with quantity 0 never change the subtotal.","A coupon other than HALF or TEN yields a discount of 0.","Calling the function twice with the same input returns deeply equal objects.","The function never reads or writes global state."]}$lz$::jsonb,
  now()
);

INSERT INTO public.reincarnations (corpse_id, target_stack, modern_code, pbt_test_code, pbt_passed, total_runs, execution_time_ms)
VALUES (
  $lz$5a3f0c1e-0001-4000-8000-000000000001$lz$::uuid,
  $lz$TypeScript 6 (strict mode, ES2022)$lz$,
  $lz$export interface InvoiceItem {
  price: number;
  quantity: number;
}

export interface InvoiceOrder {
  items: InvoiceItem[];
  taxRate: number;
  coupon: string;
}

export interface InvoiceTotals {
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
}

function round2(value: number): number {
  return Math.round(value * 100) / 100;
}

function discountFor(coupon: string, subtotal: number): number {
  if (coupon === 'HALF') return subtotal / 2;
  if (coupon === 'TEN') return subtotal * 0.1;
  return 0;
}

export function computeInvoiceTotal(order: InvoiceOrder): InvoiceTotals {
  let subtotal = 0;
  for (const item of order.items) {
    if (item.quantity === 0) continue;
    subtotal += item.price * item.quantity;
  }

  const discount = discountFor(order.coupon, subtotal);
  const taxable = subtotal - discount;
  const tax = taxable * order.taxRate;

  return {
    subtotal: round2(subtotal),
    discount: round2(discount),
    tax: round2(tax),
    total: round2(taxable + tax),
  };
}
$lz$,
  $lz$const itemArbitrary = fc.record({
  price: fc.double({ min: -1000, max: 1000, noNaN: true }),
  quantity: fc.integer({ min: 0, max: 50 }),
});

const orderArbitrary = fc.record({
  items: fc.array(itemArbitrary, { maxLength: 8 }),
  taxRate: fc.double({ min: 0, max: 1, noNaN: true }),
  coupon: fc.constantFrom('', 'HALF', 'TEN', 'NONE'),
});

return fc.property(orderArbitrary, (order) => {
  assertEquivalent(order);
});
$lz$,
  true,
  1000,
  555
);

