INSERT INTO public.seance_specs (corpse_id, requirements_md, design_md, invariants_json, approved_at)
VALUES (
  $lz$5a3f0c1e-0002-4000-8000-000000000002$lz$::uuid,
  $lz$# Requirements: Query string parser

## Acceptance Criteria

1. THE parseQueryString function SHALL accept a query string with or without a leading question mark and SHALL return an object that maps decoded keys to decoded values.
2. WHEN the input is empty or contains only a question mark, THE parseQueryString function SHALL return an empty object.
3. WHEN a pair has no equals sign, THE parseQueryString function SHALL use the empty string as its value.
4. WHEN a key appears more than once, THE parseQueryString function SHALL return an array that holds every value in order of appearance.
5. WHEN a key or a value contains a plus sign, THE parseQueryString function SHALL decode it as a space before percent-decoding.
6. IF a percent-encoded sequence is malformed, THEN THE parseQueryString function SHALL throw a URIError.
7. WHERE a key is __proto__, THE parseQueryString function SHALL ignore the pair.
$lz$,
  $lz$# Design: Query string parser

Entry function: `parseQueryString(query)`.

Input: a string, the URL query part with or without a leading question mark.

Output: an object that maps each decoded key to a decoded string, or to an array of strings when the key repeats.

The function is pure and deterministic. The TypeScript version types the result as a record of strings or string arrays, uses `startsWith` and `Array.isArray` instead of loose comparisons, and skips the `__proto__` key explicitly.$lz$,
  $lz${"entry_function":"parseQueryString","input":"string: a URL query string, with or without a leading question mark","output":"object mapping string keys to a string or to an array of strings","invariants":["Empty pairs created by consecutive ampersands are skipped.","The first occurrence of a key stores a string and later occurrences store an array of strings.","The key __proto__ never changes the prototype of the result and never appears as an own property.","A malformed percent-encoded sequence throws a URIError.","Calling the function twice with the same input returns deeply equal objects."]}$lz$::jsonb,
  now()
);

INSERT INTO public.reincarnations (corpse_id, target_stack, modern_code, pbt_test_code, pbt_passed, total_runs, execution_time_ms)
VALUES (
  $lz$5a3f0c1e-0002-4000-8000-000000000002$lz$::uuid,
  $lz$TypeScript 6 (strict mode, ES2022)$lz$,
  $lz$export type QueryValue = string | string[];
export type QueryResult = Record<string, QueryValue>;

function decodeComponent(raw: string): string {
  return decodeURIComponent(raw.replace(/\+/g, ' '));
}

export function parseQueryString(query: string): QueryResult {
  const result: QueryResult = {};
  const text = query.startsWith('?') ? query.substring(1) : query;
  if (text === '') return result;

  for (const pair of text.split('&')) {
    if (pair === '') continue;

    const separator = pair.indexOf('=');
    const rawKey = separator < 0 ? pair : pair.substring(0, separator);
    const rawValue = separator < 0 ? '' : pair.substring(separator + 1);
    const key = decodeComponent(rawKey);
    const value = decodeComponent(rawValue);

    // Assigning a string to "__proto__" is a silent no-op on a plain object. The key is skipped
    // explicitly so that the result never depends on prototype setters.
    if (key === '__proto__') continue;

    const existing = Object.hasOwn(result, key) ? result[key] : undefined;
    if (existing === undefined) {
      result[key] = value;
    } else if (Array.isArray(existing)) {
      existing.push(value);
    } else {
      result[key] = [existing, value];
    }
  }

  return result;
}
$lz$,
  $lz$const tokenArbitrary = fc.constantFrom(
  'a', 'b', 'key', '=', '&', '?', '+', '%20', '%', '%zz', '1', '__proto__', 'constructor', 'toString'
);

const rawQueryArbitrary = fc
  .array(tokenArbitrary, { maxLength: 14 })
  .map((tokens) => tokens.join(''));

const encodedPairArbitrary = fc
  .tuple(fc.string({ maxLength: 6 }), fc.string({ maxLength: 6 }))
  .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(value));

const structuredQueryArbitrary = fc
  .array(encodedPairArbitrary, { maxLength: 6 })
  .map((pairs) => pairs.join('&'));

return fc.property(fc.oneof(rawQueryArbitrary, structuredQueryArbitrary), (query) => {
  assertEquivalent(query);
});
$lz$,
  true,
  1000,
  375
);

-- Sample: Batch calculator (legacy Node callbacks)
INSERT INTO public.corpses (id, user_id, is_sample, title, source_language, original_code, code_hash, status)
VALUES (
  $lz$5a3f0c1e-0003-4000-8000-000000000003$lz$::uuid,
  NULL,
  true,
  $lz$Batch calculator (legacy Node callbacks)$lz$,
  $lz$legacy-node$lz$,
  $lz$function calculateBatch(input) {
  var jobs = input.jobs;
  var results = [];
  var failures = 0;

  function readJob(index, callback) {
    if (index >= jobs.length) {
      callback(new Error('no such job'));
      return;
    }
    callback(null, jobs[index]);
  }

  function runJob(job, error, done) {
    if (error) {
      failures = failures + 1;
      done(null);
      return;
    }
    var operators = ['+', '-', '*', '/', '%'];
    if (operators.indexOf(job.op) === -1) {
      failures = failures + 1;
      done(null);
      return;
    }
    var operation = new Function('a', 'b', 'return a ' + job.op + ' b;');
    done(operation(job.a, job.b));
  }

  readJob(0, function (error1, job1) {
    runJob(job1, error1, function (value1) {
      results.push(value1);
      readJob(1, function (error2, job2) {
        runJob(job2, error2, function (value2) {
          results.push(value2);
          readJob(2, function (error3, job3) {
            runJob(job3, error3, function (value3) {
              results.push(value3);
            });
          });
        });
      });
    });
  });

  return { results: results, failures: failures };
}
$lz$,
  $lz$a5bc2ad350e04fd0483a78643a4eea951f6849002fbd7b01b2b598dcd4a8633c$lz$,
  'RESURRECTED'
);

