  ($lz$5a3f0c1e-0003-4000-8000-000000000003$lz$::uuid, $lz$EVAL_INJECTION$lz$, $lz$FATAL$lz$, 26, $lz$Builds executable code from the job operator at run time. An unchecked operator would let input data run arbitrary code.$lz$, $lz$Replace dynamic code with a switch or a lookup of supported operator functions.$lz$),
  ($lz$5a3f0c1e-0003-4000-8000-000000000003$lz$::uuid, $lz$VAR_HOISTING$lz$, $lz$HEX$lz$, 2, $lz$The var declaration is hoisted to function scope and can be read before it is assigned, which hides ordering mistakes.$lz$, $lz$Declare values with const where they are never reassigned and with let only where they are.$lz$),
  ($lz$5a3f0c1e-0003-4000-8000-000000000003$lz$::uuid, $lz$VAR_HOISTING$lz$, $lz$HEX$lz$, 26, $lz$The var declaration inside a conditional flow is hoisted to function scope and leaks into the rest of the function.$lz$, $lz$Remove the dynamic operation and compute the value directly in a block-scoped const.$lz$);

INSERT INTO public.seance_specs (corpse_id, requirements_md, design_md, invariants_json, approved_at)
VALUES (
  $lz$5a3f0c1e-0003-4000-8000-000000000003$lz$::uuid,
  $lz$# Requirements: Batch calculator

## Acceptance Criteria

1. THE calculateBatch function SHALL return an object with a results array of exactly 3 entries and a numeric failures count.
2. WHEN a job exists at position 0, 1, or 2 and its operator is one of +, -, *, /, or %, THE calculateBatch function SHALL store the result of applying the operator to a and b at the same position in results.
3. IF a job is missing at one of the first three positions, THEN THE calculateBatch function SHALL store null at that position and SHALL increase failures by 1.
4. IF the operator of a job is not one of the supported operators, THEN THE calculateBatch function SHALL store null at that position and SHALL increase failures by 1.
5. THE calculateBatch function SHALL ignore every job after the third.
6. THE calculateBatch function SHALL NOT evaluate any operator outside the supported list.
$lz$,
  $lz$# Design: Batch calculator

Entry function: `calculateBatch(input)`.

Input: an object `{ jobs }` where `jobs` is an array of `{ a: number, b: number, op: string }`.

Output: an object `{ results, failures }`. `results` holds exactly three entries, each a number or null, and `failures` counts the null entries.

The function is pure and deterministic. The legacy version chains Node-style callbacks and builds each operation with `new Function`. The TypeScript version loops over the first three positions and selects the operation with a switch statement.$lz$,
  $lz${"entry_function":"calculateBatch","input":"object { jobs: { a: number, b: number, op: string }[] }","output":"object { results: (number | null)[], failures: number }","invariants":["results always has exactly 3 entries.","failures equals the number of null entries in results.","Only the operators +, -, *, /, and % produce a number.","Jobs after the third position never influence the output.","Calling the function twice with the same input returns deeply equal objects."]}$lz$::jsonb,
  now()
);

INSERT INTO public.reincarnations (corpse_id, target_stack, modern_code, pbt_test_code, pbt_passed, total_runs, execution_time_ms)
VALUES (
  $lz$5a3f0c1e-0003-4000-8000-000000000003$lz$::uuid,
  $lz$TypeScript 6 (strict mode, ES2022)$lz$,
  $lz$export interface BatchJob {
  a: number;
  b: number;
  op: string;
}

export interface BatchInput {
  jobs: BatchJob[];
}

export interface BatchOutput {
  results: Array<number | null>;
  failures: number;
}

const BATCH_SIZE = 3;

function applyOperator(op: string, a: number, b: number): number | null {
  switch (op) {
    case '+':
      return a + b;
    case '-':
      return a - b;
    case '*':
      return a * b;
    case '/':
      return a / b;
    case '%':
      return a % b;
    default:
      return null;
  }
}

export function calculateBatch(input: BatchInput): BatchOutput {
  const results: Array<number | null> = [];
  let failures = 0;

  for (let index = 0; index < BATCH_SIZE; index += 1) {
    const job: BatchJob | undefined = input.jobs[index];
    const value = job === undefined ? null : applyOperator(job.op, job.a, job.b);
    if (value === null) failures += 1;
    results.push(value);
  }

  return { results, failures };
}
$lz$,
  $lz$const jobArbitrary = fc.record({
  a: fc.double({ noNaN: true }),
  b: fc.double({ noNaN: true }),
  op: fc.constantFrom('+', '-', '*', '/', '%', '^', '**', 'x', ''),
});

return fc.property(fc.record({ jobs: fc.array(jobArbitrary, { maxLength: 5 }) }), (input) => {
  assertEquivalent(input);
});
$lz$,
  true,
  1000,
  351
);
